(7592598, 1224396, 65234, '<td valign="top">Love the quizzical posture. Voted earlier and this got one of my highest scores, but ... I would have smoothed out the background more (or not sharpened it). It''s a little noisy and distracting from an excellent wildlife capture.</td>', 'Love the quizzical posture. Voted earlier and this got one of my highest scores, but ... I would have smoothed out the background more (or not sharpened it). It''s a little noisy and distracting from an excellent wildlife capture.', '2018-08-16 14:34:44.000000', NULL, 1),
(7592600, 1224566, 65234, '<td valign="top">This is beautiful. I love the perspective and the inclusion of the canoe. I can see a paddle, so  I''m imagining drifting along in utter peace and just enjoying the view.</td>', 'This is beautiful. I love the perspective and the inclusion of the canoe. I can see a paddle, so  I''m imagining drifting along in utter peace and just enjoying the view.', '2018-08-16 14:37:07.000000', NULL, 1),
